<template><el-dialog :title="form.calendarId ? '编辑日历' : '新增日历'" :visible.sync="open" width="650px" :close-on-click-modal="false"><el-form :model="form" label-width="100px"><el-form-item label="日历编码" required><el-input v-model="form.calendarCode" :disabled="!!form.calendarId" /></el-form-item><el-form-item label="日历名称" required><el-input v-model="form.calendarName" /></el-form-item><el-form-item label="时区" required><el-input v-model="form.timezone" placeholder="Asia/Shanghai" /></el-form-item><el-form-item label="工作日" required><el-checkbox-group v-model="form.workDays"><el-checkbox v-for="day in days" :key="day.value" :label="day.value">{{ day.label }}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="开始时间" required><el-time-picker v-model="form.workStart" value-format="HH:mm" format="HH:mm" /></el-form-item><el-form-item label="结束时间" required><el-time-picker v-model="form.workEnd" value-format="HH:mm" format="HH:mm" /></el-form-item><el-form-item label="例外日期"><el-date-picker v-model="exceptionDate" type="date" value-format="yyyy-MM-dd" /><el-switch v-model="exceptionWorking" active-text="工作日" /><el-button @click="addException">添加</el-button><div v-for="(working, date) in form.exceptions" :key="date">{{ date }}：{{ working ? '工作日' : '休息日' }} <el-button type="text" @click="$delete(form.exceptions, date)">删除</el-button></div></el-form-item></el-form></el-form><span slot="footer"><el-button @click="open = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span></el-dialog></template>
<script>
import { field, validateCalendar } from '../resource-contract'
export default { data() { return { open: false, saving: false, exceptionDate: '', exceptionWorking: false, days: [{ value: 1, label: '一' }, { value: 2, label: '二' }, { value: 3, label: '三' }, { value: 4, label: '四' }, { value: 5, label: '五' }, { value: 6, label: '六' }, { value: 7, label: '日' }], form: {} } }, methods: { show(row) { const exception = field(row, 'exception_json', 'exceptionJson'); this.form = { calendarId: field(row, 'calendar_id', 'calendarId'), calendarCode: field(row, 'calendar_code', 'calendarCode') || '', calendarName: field(row, 'calendar_name', 'calendarName') || '', timezone: field(row, 'timezone', 'timezone') || 'Asia/Shanghai', workDays: String(field(row, 'work_days', 'workDays') || '1,2,3,4,5').split(',').map(Number), workStart: field(row, 'work_start', 'workStart') || '09:00', workEnd: field(row, 'work_end', 'workEnd') || '18:00', exceptions: exception ? JSON.parse(exception) : {}, status: field(row, 'status', 'status') || '0' }; this.open = true }, addException() { if (this.exceptionDate) this.$set(this.form.exceptions, this.exceptionDate, this.exceptionWorking) }, async save() { try { this.saving = true; await this.$emit('save', validateCalendar(this.form)); this.open = false } catch (error) { this.$modal.msgError(error.message || '保存失败') } finally { this.saving = false } } } }
</script>
